    int a[5]={6,2,9,1,4};
    for(int i=0;i<4;++i){
        int minIndex=i;
        for(int j=i+1;j<5;++j) if(a[j]<a[minIndex]) minIndex=j;
        int t=a[i]; a[i]=a[minIndex]; a[minIndex]=t;
    }
    for(int x:a) cout<<x<<" ";
    return 0;
}

